package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.junit.jupiter.api.Test;
import static com.consense.service.drafting.DraftReviewGraph.*;
import static org.junit.jupiter.api.Assertions.*;

/** Explicit current-source readers receive definitions, never another instruction's patch authority. */
class DraftKnownRootReadOnlyRelationTest {
    static final String SHA=String.join("",Collections.nCopies(64,"a")),OTHER=String.join("",Collections.nCopies(64,"b")),READER="Review the related current alternative.";

    @Test void aSuppliedGuidanceRelationExposesTheRootWithoutAddingAnOwnerOrChangingItsProof(){
        ObjectNode reading=source("1","NTT",SHA);reader(reading).putArray("guidanceNoteIds").add("owner-note");List<Map<String,Object>> tasks=tasks(reading);DraftKnownRoots.Result known=build(Collections.singletonList(reading),tasks);String owner=task(tasks,"owner-note"),reader=task(tasks,"reader-note"),before=JsonUtils.write(known.roots());Map<String,Map<String,Object>> visible=known.forTasks(Collections.singleton(reader));assertEquals(Collections.singleton("worksSubjectToExcision"),visible.keySet());assertReadOnly(visible,reader);Map<String,Object> ref=map(known.roots().get(0).get("currentDefinitionReference"));assertEquals(Collections.singletonList(owner),ref.get("taskIds"));assertEquals(Collections.singleton(owner),map(ref.get("taskQuotes")).keySet());assertEquals(before,JsonUtils.write(known.roots()));assertTrue(known.forTasks(Collections.singleton(owner)).containsKey("worksSubjectToExcision"));
    }

    @Test void aRealCurrentScopeRelationCanSupplyTheSameReadOnlyReference(){
        ObjectNode reading=source("1","NTT",SHA);reader(reading).putArray("targetGroupIds").add("owner-scope");List<Map<String,Object>> tasks=tasks(reading);Map<String,Object> readerTask=tasks.stream().filter(row->"reader-note".equals(row.get("sourceObservationId"))).findFirst().orElseThrow();Map<String,Object> payload=DraftReviewDiscovery.sourceTaskPayload(reading,readerTask);assertEquals(1,list(payload.get("scopeCandidates")).size());DraftKnownRoots.Result known=build(Collections.singletonList(reading),tasks);assertEquals(Collections.singleton("worksSubjectToExcision"),known.forTasks(Collections.singleton(task(tasks,"reader-note"))).keySet());assertReadOnly(known.forTasks(Collections.singleton(task(tasks,"reader-note"))),task(tasks,"reader-note"));
    }

    @Test void unrelatedMissingStaleUnboundAndForgedReadersCannotAcquireAliasesOrBreakAnotherProof(){
        for(String defect:Arrays.asList("unrelated","missing-note","missing-scope","stale-member","unclosed-reader","unbound-source","forged-task-id","forged-task-sha","missing-task-observation")){
            ObjectNode reading=source("1","NTT",SHA),reader=reader(reading);reader.putArray("guidanceNoteIds").add("owner-note");
            if("unrelated".equals(defect))reader.remove("guidanceNoteIds");if("missing-note".equals(defect))reader.putArray("guidanceNoteIds").add("missing-note");if("missing-scope".equals(defect)){reader.remove("guidanceNoteIds");reader.putArray("targetGroupIds").add("missing-scope");}if("stale-member".equals(defect))((ObjectNode)reading.path("sourceMembers").path(2).path("sourcePosition")).put("sourceSha256",OTHER);if("unclosed-reader".equals(defect))reader.put("captureComplete",false);
            List<Map<String,Object>> tasks=tasks(reading);Map<String,Object> task=tasks.stream().filter(row->"reader-note".equals(row.get("sourceObservationId"))).findFirst().orElseThrow();if("forged-task-id".equals(defect))task.put("taskId","source-000000000000000000000000");if("forged-task-sha".equals(defect))task.put("sourceSha256",OTHER);if("missing-task-observation".equals(defect))task.put("sourceObservationId","missing-note");if("unbound-source".equals(defect))reading.put("evidenceStatus","unbound");DraftKnownRoots.Result known=assertDoesNotThrow(()->build(Collections.singletonList(reading),tasks),defect);assertTrue(known.forTasks(Collections.singleton(text(task.get("taskId")))).isEmpty(),defect);if(!"unbound-source".equals(defect))assertEquals(1,known.roots().size(),"The unrelated malformed reader must not erase the valid owner: "+defect);
        }
    }

    @Test void theSameObservationLabelOnAnotherSourceOrHashDoesNotReferenceTheOriginalProof(){
        for(String foreignSha:Arrays.asList(SHA,OTHER)){ObjectNode owner=source("1","NTT",SHA),foreign=source("2","SCT",foreignSha);((ObjectNode)foreign.path("guidanceNotes").path(0)).put("text","A different current instruction.");((ObjectNode)foreign.path("sourceMembers").path(0).path("textObservation")).put("text","A different current instruction.");((ObjectNode)foreign.path("guidanceNotes").path(0).path("memberRanges").path(0)).put("end","A different current instruction.".length());reader(foreign).putArray("guidanceNoteIds").add("owner-note");List<Map<String,Object>> tasks=new ArrayList<>(tasks(owner));List<Map<String,Object>> foreignTasks=tasks(foreign);tasks.addAll(foreignTasks);DraftKnownRoots.Result known=build(Arrays.asList(owner,foreign),tasks);assertEquals(1,known.roots().size());assertTrue(known.forTasks(Collections.singleton(task(foreignTasks,"reader-note"))).isEmpty());}
    }

    @Test void aReaderReceivesOnlyItsRelatedDefinitionClosureRatherThanEveryRootOnTheSource(){
        ObjectNode reading=source("1","NTT",SHA);addGuidance(reading,"procedure",DraftBusinessRules.standardParagraph("NTT",172)+"\n"+DraftBusinessRules.standardParagraph("NTT",173),DraftBusinessRules.standardParagraph("NTT",166));reader(reading).putArray("guidanceNoteIds").add("procedure");List<Map<String,Object>> tasks=tasks(reading);DraftKnownRoots.Result known=build(Collections.singletonList(reading),tasks);Map<String,Map<String,Object>> visible=known.forTasks(Collections.singleton(task(tasks,"reader-note")));assertTrue(visible.keySet().containsAll(Arrays.asList("electronicTendering","twoEnvelopeTendering","otherTenderingArrangement")));assertFalse(visible.containsKey("worksSubjectToExcision"));assertReadOnly(visible,task(tasks,"reader-note"));
    }

    @Test void markerAndFieldReadersDoNotGainUnverifiedNativeAuthorityFromReferenceStrings(){
        ObjectNode reading=source("1","NTT",SHA);ObjectNode marker=reading.withArray("markerCandidates").addObject().put("id","marker-reader").put("memberId","reader-note-member").put("channel","text");marker.putObject("localSentenceObservation").put("text",READER).put("start",0).put("end",READER.length());marker.putArray("guidanceNoteIds").add("owner-note");ObjectNode field=reading.withArray("groups").addObject().put("id","field-reader").put("kind","native_source_field_candidate").put("guidanceNoteId","owner-note").put("scopeComplete",true).put("text",READER);field.putArray("memberRanges").addObject().put("memberId","reader-note-member").put("channel","text").put("start",0).put("end",READER.length());List<Map<String,Object>> tasks=tasks(reading);DraftKnownRoots.Result known=build(Collections.singletonList(reading),tasks);for(String id:Arrays.asList("marker-reader","field-reader")){String task=task(tasks,id);assertFalse(task.isEmpty());assertTrue(known.forTasks(Collections.singleton(task)).isEmpty(),"Non-guidance readers need a separate verified native reader seam: "+id);}
    }

    static void assertReadOnly(Map<String,Map<String,Object>> visible,String reader){assertFalse(visible.isEmpty());for(Map<String,Object> node:visible.values()){Map<String,Object> reference=map(node.get("currentDefinitionReference"));assertTrue(list(reference.get("taskIds")).isEmpty());assertTrue(map(reference.get("taskQuotes")).isEmpty());assertFalse(list(reference.get("taskIds")).contains(reader));assertFalse(Boolean.TRUE.equals(reference.get("editableAuthority")));}}
    static List<Map<String,Object>> tasks(ObjectNode reading){return new ArrayList<>(DraftReviewDiscovery.sourceTasks(Collections.singletonList(reading)));}
    static String task(List<Map<String,Object>> tasks,String observation){return text(tasks.stream().filter(row->observation.equals(row.get("sourceObservationId"))).findFirst().orElseThrow(()->new AssertionError(observation)).get("taskId"));}
    static ObjectNode reader(ObjectNode reading){return (ObjectNode)reading.path("guidanceNotes").path(1);}
    static DraftKnownRoots.Result build(List<ObjectNode> readings,List<Map<String,Object>> tasks){Map<String,JsonNode> byId=new LinkedHashMap<>();List<Object> identities=new ArrayList<>();Map<String,Object> selected=new LinkedHashMap<>();for(ObjectNode source:readings){String id=source.path("id").asText(),family=source.path("fileKey").asText();byId.put(id,source);identities.add(obj("id",id,"fileKey",family,"sourceSha256",source.path("sourceSha256").asText(),"evidenceStatus",source.path("evidenceStatus").asText()));selected.put(family,id);}Map<String,Object> graph=obj("sources",identities,"selectedDocuments",selected,"graph",obj("variables",new ArrayList<>()));return DraftKnownRoots.build(byId,tasks,DraftDiscoveryGroups.currentTemplateIndexes(byId),graph);}
    static ObjectNode source(String id,String family,String sha){ObjectNode reading=JsonUtils.mapper().createObjectNode().put("id",id).put("sourceDocumentId",Long.parseLong(id)).put("fileKey",family).put("format","docx").put("sourceSha256",sha).put("evidenceStatus","bound").put("analysisRevision","analysis-1").put("analysisInputSha256",sha).put("analysisSha256",sha);for(String field:Arrays.asList("guidanceNotes","groups","markerCandidates","sourceMembers","paragraphs"))reading.putArray(field);addGuidance(reading,"owner-note",DraftBusinessRules.standardParagraph("NTT",244),DraftBusinessRules.standardParagraph("NTT",243));addGuidance(reading,"reader-note",READER,"");return reading;}
    static void addGuidance(ObjectNode reading,String id,String quote,String body){ObjectNode note=reading.withArray("guidanceNotes").addObject().put("id",id).put("text",quote).put("captureComplete",true);note.putArray("orderedMemberIds").add(id+"-member");note.putArray("memberRanges").addObject().put("memberId",id+"-member").put("channel","text").put("start",0).put("end",quote.length());member(reading,id+"-member",quote);if(!body.isEmpty()){String scopeId="owner-note".equals(id)?"owner-scope":id+"-scope";ObjectNode scope=reading.withArray("groups").addObject().put("id",scopeId).put("text",body).put("scopeComplete",true);scope.putArray("guidanceNoteIds").add(id);scope.putArray("memberRanges").addObject().put("memberId",id+"-body").put("channel","text").put("start",0).put("end",body.length());member(reading,id+"-body",body);}}
    static void member(ObjectNode reading,String id,String text){ObjectNode member=reading.withArray("sourceMembers").addObject().put("id",id);member.putObject("textObservation").put("text",text);member.putObject("sourcePosition").put("sourceSha256",reading.path("sourceSha256").asText()).put("partName","word/document.xml").put("nodePath","/current/"+id);}
}
